func requireCandidateReviewPass(ctx context.Context, db *store.DB, project store.Project, task store.Task, candidate store.ValidationCandidate) error {
	targets, err := changeCandidateTargetsForCandidate(ctx, db, project, task, &candidate)
	if err != nil {
		return err
	}
	if err := ensureReviewCarryForCandidate(ctx, db, project, task, targets, &candidate); err != nil {
		return err
	}
	evidence, err := db.ReviewEvidenceFor(ctx, task.ID, targets)
	if err != nil {
		return err
	}
	plan, planErr := task.AdmittedPlan()
	if planErr != nil {
		return admittedPlanFailure(planErr)
	}
	findings, err := db.ReviewFindingsForTask(ctx, task.ID)
	if err != nil {
		return err
	}
	for _, finding := range findings {
		if reviewFindingBlocks(finding, plan) {
			return axi.Failure("review_findings_open", "candidate has a blocking Review finding that is not fixed or accepted by the User", false, "Fix it, record a qualifying User disposition, or complete a passing Review")
		}
	}
	if !evidence.Complete {
		if requireFrozenReviewLoop(plan) != nil {
			return axi.Failure("validation_review_required", "the current private candidate "+shortSHA(candidate.CandidateSHA)+" has no passing Review, proved Review carry, or exact-head User disposition", false,
				"Dispatch an independent Review Task with `review_of: "+taskIDString(task.Seq)+"` and wait for a pass on this exact candidate")
		}
		// No Review Round can cover this candidate once Review and repair
		// rounds have spent the frozen cap, so only the User's cap Decision
		// can unblock publication.
		usage, err := db.ReviewCapUsage(ctx, task.ID)
		if err != nil {
			return err
		}
		max := plan.ValidationLoops.MaxReviewRounds()
		if used := reviewCapUsed(task, usage); used >= max {
			binding, err := reviewCapHead(ctx, db, project, task)
			if err != nil {
				return err
			}
			return reviewCapExhausted(ctx, db, project, task, binding, used, max)
		}
		help := "Run `posse review start " + taskIDString(task.Seq) + " --profile <profile>` and wait for a pass on this exact candidate"
		return axi.Failure("validation_review_required", "the current private candidate "+shortSHA(candidate.CandidateSHA)+" has no passing Review, proved Review carry, or exact-head User disposition", false, help)
	}
	return nil
}

